-- Baseline structural schema; data seeds are not migrations.
CREATE TABLE IF NOT EXISTS sys_department (id text PRIMARY KEY, pid text REFERENCES sys_department(id) ON DELETE RESTRICT, name text NOT NULL, leader text NOT NULL DEFAULT '', status integer NOT NULL DEFAULT 1, sort integer NOT NULL DEFAULT 1, remark text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (pid, name), UNIQUE (pid, sort));
CREATE TABLE IF NOT EXISTS sys_position (id text PRIMARY KEY, dept_id text NOT NULL REFERENCES sys_department(id) ON DELETE RESTRICT, code text NOT NULL UNIQUE, name text NOT NULL, status integer NOT NULL DEFAULT 1, sort integer NOT NULL DEFAULT 1, remark text NOT NULL DEFAULT '', UNIQUE (dept_id, name), UNIQUE (dept_id, sort));
CREATE TABLE IF NOT EXISTS sys_user (id text PRIMARY KEY, username text NOT NULL UNIQUE, password text NOT NULL, real_name text NOT NULL, phone text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', dept_id text REFERENCES sys_department(id) ON DELETE RESTRICT, position_id text REFERENCES sys_position(id) ON DELETE RESTRICT, leader_id text REFERENCES sys_user(id) ON DELETE SET NULL, status integer NOT NULL DEFAULT 1, locked boolean NOT NULL DEFAULT false, must_change_password boolean NOT NULL DEFAULT false, login_failed_count integer NOT NULL DEFAULT 0, locked_until timestamptz, remark text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), last_login_at timestamptz);
ALTER TABLE sys_user ADD COLUMN IF NOT EXISTS login_failed_count integer NOT NULL DEFAULT 0;
ALTER TABLE sys_user ADD COLUMN IF NOT EXISTS locked_until timestamptz;
CREATE TABLE IF NOT EXISTS sys_role (id text PRIMARY KEY, code text NOT NULL UNIQUE, name text NOT NULL, builtin boolean NOT NULL DEFAULT false, status integer NOT NULL DEFAULT 1, data_scope text NOT NULL DEFAULT 'self', remark text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS sys_user_role (user_id text NOT NULL REFERENCES sys_user(id) ON DELETE CASCADE, role_id text NOT NULL REFERENCES sys_role(id) ON DELETE CASCADE, PRIMARY KEY (user_id, role_id));
CREATE TABLE IF NOT EXISTS sys_menu (id text PRIMARY KEY, pid text REFERENCES sys_menu(id) ON DELETE RESTRICT, name text NOT NULL UNIQUE, title text NOT NULL, type text NOT NULL, path text NOT NULL DEFAULT '', component text NOT NULL DEFAULT '', auth_code text NOT NULL DEFAULT '', icon text NOT NULL DEFAULT '', status integer NOT NULL DEFAULT 1, sort integer NOT NULL DEFAULT 1, UNIQUE (pid, path));
CREATE TABLE IF NOT EXISTS sys_role_menu (role_id text NOT NULL REFERENCES sys_role(id) ON DELETE CASCADE, menu_id text NOT NULL REFERENCES sys_menu(id) ON DELETE CASCADE, PRIMARY KEY (role_id, menu_id));
-- 操作权限沿用 sys_menu(type=button, auth_code) 作为兼容模型；独立权限表预留给后续多接口映射。
CREATE TABLE IF NOT EXISTS sys_setting (setting_key text PRIMARY KEY, setting_value jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sys_operation_log (id text PRIMARY KEY, operator text NOT NULL, module text NOT NULL, action text NOT NULL, target text NOT NULL DEFAULT '', result text NOT NULL, ip text NOT NULL DEFAULT '', detail text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS crm_customer (id text PRIMARY KEY, name text NOT NULL UNIQUE, short_name text NOT NULL DEFAULT '', type text NOT NULL DEFAULT '企业', industry text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', region text NOT NULL DEFAULT '', source text NOT NULL DEFAULT '', level text NOT NULL DEFAULT '普通', owner_id text REFERENCES sys_user(id) ON DELETE SET NULL, status integer NOT NULL DEFAULT 1, remark text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE crm_customer ADD COLUMN IF NOT EXISTS deleted boolean NOT NULL DEFAULT false;
ALTER TABLE crm_customer ADD COLUMN IF NOT EXISTS deleted_at timestamptz;
ALTER TABLE crm_customer ADD COLUMN IF NOT EXISTS deleted_by text REFERENCES sys_user(id) ON DELETE SET NULL;
ALTER TABLE crm_customer ADD COLUMN IF NOT EXISTS delete_reason text NOT NULL DEFAULT '';
CREATE TABLE IF NOT EXISTS crm_contact (id text PRIMARY KEY, customer_id text NOT NULL REFERENCES crm_customer(id) ON DELETE RESTRICT, name text NOT NULL, gender text NOT NULL DEFAULT '', position text NOT NULL DEFAULT '', contact_type text NOT NULL DEFAULT '其他', mobile text NOT NULL DEFAULT '', telephone text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', wechat text NOT NULL DEFAULT '', is_primary boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT '正常', remark text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE crm_contact ADD COLUMN IF NOT EXISTS deleted boolean NOT NULL DEFAULT false;
ALTER TABLE crm_contact ADD COLUMN IF NOT EXISTS deleted_at timestamptz;
ALTER TABLE crm_contact ADD COLUMN IF NOT EXISTS deleted_by text REFERENCES sys_user(id) ON DELETE SET NULL;
ALTER TABLE crm_contact ADD COLUMN IF NOT EXISTS delete_reason text NOT NULL DEFAULT '';
ALTER TABLE crm_contact ADD COLUMN IF NOT EXISTS contact_business text NOT NULL DEFAULT '';
CREATE TABLE IF NOT EXISTS crm_follow_up (id text PRIMARY KEY, customer_id text NOT NULL REFERENCES crm_customer(id) ON DELETE RESTRICT, contact_id text REFERENCES crm_contact(id) ON DELETE SET NULL, follow_up_time timestamptz NOT NULL, follow_up_type text NOT NULL DEFAULT '电话沟通', subject text NOT NULL, content text NOT NULL, result text NOT NULL DEFAULT '', intention_level text NOT NULL DEFAULT '中', next_plan text NOT NULL DEFAULT '', next_follow_time timestamptz, status text NOT NULL DEFAULT '待跟进', owner_id text REFERENCES sys_user(id) ON DELETE SET NULL, remark text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE crm_follow_up ADD COLUMN IF NOT EXISTS deleted boolean NOT NULL DEFAULT false;
ALTER TABLE crm_follow_up ADD COLUMN IF NOT EXISTS deleted_at timestamptz;
ALTER TABLE crm_follow_up ADD COLUMN IF NOT EXISTS deleted_by text REFERENCES sys_user(id) ON DELETE SET NULL;
ALTER TABLE crm_follow_up ADD COLUMN IF NOT EXISTS delete_reason text NOT NULL DEFAULT '';
ALTER TABLE crm_follow_up ADD COLUMN IF NOT EXISTS opportunity_id text;
CREATE TABLE IF NOT EXISTS crm_opportunity (id text PRIMARY KEY, customer_id text NOT NULL REFERENCES crm_customer(id) ON DELETE RESTRICT, primary_contact_id text REFERENCES crm_contact(id) ON DELETE SET NULL, owner_id text REFERENCES sys_user(id) ON DELETE SET NULL, name text NOT NULL, source text NOT NULL DEFAULT '', stage text NOT NULL DEFAULT '初步接触', status text NOT NULL DEFAULT '进行中', amount numeric(14,2) NOT NULL DEFAULT 0, probability numeric(5,2) NOT NULL DEFAULT 10, expected_close_date date, next_plan text NOT NULL DEFAULT '', next_follow_time timestamptz, risk_level text NOT NULL DEFAULT '正常', description text NOT NULL DEFAULT '', won_at timestamptz, lost_at timestamptz, lost_reason text NOT NULL DEFAULT '', deleted boolean NOT NULL DEFAULT false, deleted_at timestamptz, deleted_by text REFERENCES sys_user(id) ON DELETE SET NULL, delete_reason text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(customer_id,name));
CREATE TABLE IF NOT EXISTS crm_opportunity_stage_history (id text PRIMARY KEY, opportunity_id text NOT NULL REFERENCES crm_opportunity(id) ON DELETE CASCADE, from_stage text NOT NULL DEFAULT '', to_stage text NOT NULL DEFAULT '', operator_id text REFERENCES sys_user(id) ON DELETE SET NULL, note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_crm_opportunity_stage_history_opportunity ON crm_opportunity_stage_history(opportunity_id, created_at DESC);
CREATE TABLE IF NOT EXISTS crm_contract (id text PRIMARY KEY, contract_no text NOT NULL UNIQUE, contract_name text NOT NULL, customer_id text NOT NULL REFERENCES crm_customer(id) ON DELETE RESTRICT, contact_name text NOT NULL DEFAULT '', project_name text NOT NULL DEFAULT '', project_no text NOT NULL DEFAULT '', archive_no text NOT NULL DEFAULT '', archived_at date, signed_at date, amount numeric(14,2) NOT NULL DEFAULT 0, owner_id text REFERENCES sys_user(id) ON DELETE SET NULL, project_type text NOT NULL DEFAULT '文档', payment_method text NOT NULL DEFAULT '', quality_deposit numeric(14,2) NOT NULL DEFAULT 0, project_period text NOT NULL DEFAULT '', status text NOT NULL DEFAULT '执行中', remark text NOT NULL DEFAULT '', items jsonb NOT NULL DEFAULT '[]'::jsonb, deleted boolean NOT NULL DEFAULT false, deleted_at timestamptz, deleted_by text REFERENCES sys_user(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_crm_contract_customer ON crm_contract(customer_id);
CREATE INDEX IF NOT EXISTS idx_crm_contract_signed_at ON crm_contract(signed_at DESC);
CREATE TABLE IF NOT EXISTS crm_customer_invoice_profile (id text PRIMARY KEY, customer_id text NOT NULL REFERENCES crm_customer(id) ON DELETE RESTRICT, invoice_title text NOT NULL, taxpayer_no text NOT NULL, invoice_type text NOT NULL DEFAULT '增值税普通发票', registered_address text NOT NULL DEFAULT '', registered_phone text NOT NULL DEFAULT '', bank_name text NOT NULL DEFAULT '', bank_account text NOT NULL DEFAULT '', invoice_email text NOT NULL DEFAULT '', invoice_phone text NOT NULL DEFAULT '', effective_from date NOT NULL DEFAULT CURRENT_DATE, effective_to date, is_current boolean NOT NULL DEFAULT true, status text NOT NULL DEFAULT '当前有效', change_reason text NOT NULL DEFAULT '', remark text NOT NULL DEFAULT '', created_by text REFERENCES sys_user(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_customer_invoice_profile_customer ON crm_customer_invoice_profile(customer_id,effective_from DESC);
CREATE UNIQUE INDEX IF NOT EXISTS uq_customer_invoice_profile_current ON crm_customer_invoice_profile(customer_id) WHERE is_current=true;
CREATE TABLE IF NOT EXISTS crm_contract_invoice (id text PRIMARY KEY, contract_id text NOT NULL REFERENCES crm_contract(id) ON DELETE RESTRICT, customer_id text NOT NULL REFERENCES crm_customer(id) ON DELETE RESTRICT, invoice_profile_id text REFERENCES crm_customer_invoice_profile(id) ON DELETE SET NULL, invoice_amount numeric(14,2) NOT NULL CHECK (invoice_amount > 0), invoice_type text NOT NULL DEFAULT '进度款', invoice_no text NOT NULL DEFAULT '', issued_at date, status text NOT NULL DEFAULT '有效', file_id text NOT NULL DEFAULT '', file_name text NOT NULL DEFAULT '', file_size integer NOT NULL DEFAULT 0, remark text NOT NULL DEFAULT '', created_by text REFERENCES sys_user(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_contract_invoice_contract ON crm_contract_invoice(contract_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_contract_invoice_customer ON crm_contract_invoice(customer_id);
CREATE TABLE IF NOT EXISTS crm_contract_payment (id text PRIMARY KEY, contract_id text NOT NULL REFERENCES crm_contract(id) ON DELETE RESTRICT, customer_id text REFERENCES crm_customer(id) ON DELETE SET NULL, payment_amount numeric(14,2) NOT NULL CHECK (payment_amount > 0), payment_date date, payment_method text NOT NULL DEFAULT '', payment_account text NOT NULL DEFAULT '', receipt_no text NOT NULL DEFAULT '', status text NOT NULL DEFAULT '已到账', invoice_id text REFERENCES crm_contract_invoice(id) ON DELETE SET NULL, remark text NOT NULL DEFAULT '', created_by text REFERENCES sys_user(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_contract_payment_contract ON crm_contract_payment(contract_id, payment_date DESC, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_contract_payment_customer ON crm_contract_payment(customer_id);
ALTER TABLE crm_contract_payment ALTER COLUMN contract_id DROP NOT NULL;
CREATE TABLE IF NOT EXISTS crm_customer_transfer (id text PRIMARY KEY, from_owner_id text REFERENCES sys_user(id) ON DELETE SET NULL, to_owner_id text NOT NULL REFERENCES sys_user(id) ON DELETE RESTRICT, reason text NOT NULL DEFAULT '', remark text NOT NULL DEFAULT '', status text NOT NULL DEFAULT '已生效', customer_count integer NOT NULL DEFAULT 0, created_by text REFERENCES sys_user(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), effective_at timestamptz NOT NULL DEFAULT now(), reversed_at timestamptz, reversed_by text REFERENCES sys_user(id) ON DELETE SET NULL, reverse_reason text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS crm_customer_transfer_detail (id text PRIMARY KEY, transfer_id text NOT NULL REFERENCES crm_customer_transfer(id) ON DELETE CASCADE, customer_id text NOT NULL REFERENCES crm_customer(id) ON DELETE RESTRICT, old_owner_id text REFERENCES sys_user(id) ON DELETE SET NULL, new_owner_id text NOT NULL REFERENCES sys_user(id) ON DELETE RESTRICT);
CREATE INDEX IF NOT EXISTS idx_customer_transfer_created_at ON crm_customer_transfer(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_customer_transfer_detail_transfer ON crm_customer_transfer_detail(transfer_id);
CREATE TABLE IF NOT EXISTS hr_employee (id text PRIMARY KEY, employee_no text NOT NULL DEFAULT '', name text NOT NULL, gender text NOT NULL DEFAULT '', birthday date, mobile text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', id_card_no text NOT NULL DEFAULT '', bank_name text NOT NULL DEFAULT '', bank_account text NOT NULL DEFAULT '', emergency_contact text NOT NULL DEFAULT '', emergency_mobile text NOT NULL DEFAULT '', dept_name text NOT NULL DEFAULT '', position text NOT NULL DEFAULT '', entry_date date, status text NOT NULL DEFAULT '在职', labor_contract_start date, labor_contract_end date, labor_contract_no text NOT NULL DEFAULT '', remark text NOT NULL DEFAULT '', created_by text REFERENCES sys_user(id) ON DELETE SET NULL, updated_by text REFERENCES sys_user(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE hr_employee ADD COLUMN IF NOT EXISTS labor_contract_file jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE hr_employee ADD COLUMN IF NOT EXISTS id_card_file jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE hr_employee ADD COLUMN IF NOT EXISTS bank_card_file jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE hr_employee ADD COLUMN IF NOT EXISTS id_card_front_file jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE hr_employee ADD COLUMN IF NOT EXISTS id_card_back_file jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE hr_employee ADD COLUMN IF NOT EXISTS bank_card_file jsonb NOT NULL DEFAULT '{}'::jsonb;
CREATE UNIQUE INDEX IF NOT EXISTS uq_hr_employee_no ON hr_employee(employee_no) WHERE employee_no <> '';
CREATE INDEX IF NOT EXISTS idx_hr_employee_birthday ON hr_employee(birthday);
CREATE INDEX IF NOT EXISTS idx_hr_employee_contract_end ON hr_employee(labor_contract_end);
